'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var isNegativeZero = require( '@stdlib/math-base-assert-is-negative-zero' );
var isPositiveZero = require( '@stdlib/math-base-assert-is-positive-zero' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var max = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof max, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var v;

	v = max( NaN, 3.14 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = max( 3.14, NaN );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+Infinity` if provided `+Infinity`', function test( t ) {
	var v;

	v = max( PINF, 3.14 );
	t.strictEqual( v, PINF, 'returns expected value' );

	v = max( 3.14, PINF );
	t.strictEqual( v, PINF, 'returns expected value' );

	t.end();
});

tape( 'the function returns a correctly signed zero', function test( t ) {
	var v;

	v = max( +0.0, -0.0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns expected value' );

	v = max( -0.0, +0.0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns expected value' );

	v = max( -0.0, -0.0 );
	t.strictEqual( isNegativeZero( v ), true, 'returns expected value' );

	v = max( +0.0, +0.0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the maximum value', function test( t ) {
	var v;

	v = max( 4.2, 3.14 );
	t.strictEqual( v, 4.2, 'returns expected value' );

	v = max( -4.2, 3.14 );
	t.strictEqual( v, 3.14, 'returns expected value' );

	t.end();
});","lineStart":1,"lineEnd":91,"totalLines":91,"truncated":false}},"title":"repos/pc-lib-3456/math-base-special-max/test/test.js","time":{"start":1783261821700,"end":1783261821702}},"id":"prt_f32affa3b001S7sWhth7JrU9vI","sessionID":"ses_0cd5088c8ffewnmvVmUIgq0GqU","messageID":"msg_f32aff0be001OyHQPTWdMYKDAZ"}}

